import{$ as e,Dt as t,Y as n,ht as r,it as i,nt as a,o,rt as s,tt as c,yt as l}from"./chunks/framework.BDx6F-5s.js";var u=JSON.parse(`{"title":"XP, Scrum, Kanban Comparison and Practical Application Strategy","description":"Understand the differences and relationships between XP, Scrum, and Kanban at a glance, and we provide a detailed guide on integrating and applying these three agile methodologies in practice. Easily implement project management and software quality improvement with step-by-step checklists and diagrams.","frontmatter":{"title":"XP, Scrum, Kanban Comparison and Practical Application Strategy","description":"Understand the differences and relationships between XP, Scrum, and Kanban at a glance, and we provide a detailed guide on integrating and applying these three agile methodologies in practice. Easily implement project management and software quality improvement with step-by-step checklists and diagrams.","head":[["meta",{"name":"keywords","content":"Agile Methodology, XP(eXtreme Programming), Scrum, Kanban, Scrumban, Software Development Process, Agile Integration Guide, Agile Practices, Software Quality Improvement, Project Management"}],["meta",{"property":"og:title","content":"Developer Role in the AI Era: XP, Scrum, Kanban Integration Guide | Agile Methodology Comparison"}],["meta",{"property":"og:description","content":"Understand the differences and relationships between XP, Scrum, and Kanban at a glance, and we provide a detailed guide on integrating and applying these three agile methodologies in practice. Easily implement project management and software quality improvement with step-by-step checklists and diagrams."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/xp_scrum_kanban.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/agile/xp_scrum_kanban.html"}]],"sort":8000},"headers":[],"relativePath":"en/agile/xp_scrum_kanban.md","filePath":"en/agile/xp_scrum_kanban.md","lastUpdated":1787438897000}`),d={name:`en/agile/xp_scrum_kanban.md`};function f(o,u,d,f,p,m){let h=l(`Mermaid`);return r(),c(`div`,null,[u[1]||=a(`<h2 id="xp-scrum-kanban-integration-guide-agile-development-methodology-comparison-and-practical-application-strategy" tabindex="-1">XP, Scrum, Kanban Integration Guide: Agile Development Methodology Comparison and Practical Application Strategy <a class="header-anchor" href="#xp-scrum-kanban-integration-guide-agile-development-methodology-comparison-and-practical-application-strategy" aria-label="Permalink to “XP, Scrum, Kanban Integration Guide: Agile Development Methodology Comparison and Practical Application Strategy”">​</a></h2><h3 id="introduction-the-essence-and-evolution-of-agile" tabindex="-1">Introduction: The Essence and Evolution of Agile <a class="header-anchor" href="#introduction-the-essence-and-evolution-of-agile" aria-label="Permalink to “Introduction: The Essence and Evolution of Agile”">​</a></h3><p>Agile, as the word &quot;agile&quot; means, is a collection of software development philosophies and frameworks aimed at responding quickly to changing requirements and continuously delivering value. The &#39;Manifesto for Agile Software Development&#39; published in 2001 values <strong>individuals and interactions</strong> over processes and tools, <strong>working software</strong> over comprehensive documentation, <strong>customer collaboration</strong> over contract negotiation, and <strong>responding to change</strong> over following a plan.</p><p>This guide provides a comparative analysis of three representative methodologies realizing Agile: eXtreme Programming (XP), Scrum, and Kanban, explains their interrelationships, and presents a methodology to utilize them integratively.</p><hr><h3 id="_1-xp-scrum-kanban-comparison" tabindex="-1">1. XP, Scrum, Kanban Comparison <a class="header-anchor" href="#_1-xp-scrum-kanban-comparison" aria-label="Permalink to “1. XP, Scrum, Kanban Comparison”">​</a></h3><h4 id="_1-1-extreme-programming-xp-engineering-practices" tabindex="-1"><strong>1.1 eXtreme Programming (XP) - Engineering Practices</strong> <a class="header-anchor" href="#_1-1-extreme-programming-xp-engineering-practices" aria-label="Permalink to “1.1 eXtreme Programming (XP) - Engineering Practices”">​</a></h4><p>XP is a <strong>development framework</strong> focused on improving software quality and maximizing the development team&#39;s productivity and responsiveness. Its core goal is to respond to rapidly changing customer requirements.</p><ul><li><p><strong>Philosophy:</strong> &quot;If this is a good thing, taking it to the extreme would be even better.&quot;</p></li><li><p><strong>Scope of Application:</strong> Mainly deeply involved in the <strong>software code development stage</strong>.</p></li><li><p><strong>Cycle:</strong> Development proceeds in short cycles (usually 1-2 weeks) called <strong>Iterations</strong>.</p></li><li><p><strong>Core Practices:</strong></p><ul><li><strong>Pair Programming:</strong> Two developers work at one computer, reviewing code and sharing knowledge in real-time.</li><li><strong>Test Driven Development (TDD):</strong> <strong>Write failing test code first</strong> for the code to be written, and then write the minimum code to pass the test. Repeat this to increase code reliability.</li><li><strong>Continuous Integration (CI):</strong> Integrate code into the main repository multiple times a day and run automated tests to discover problems early.</li><li><strong>Refactoring:</strong> Improve the internal structure of the code without changing functionality to increase readability and maintainability.</li><li><strong>Simple Design:</strong> Design the simplest system that satisfies current requirements.</li><li><strong>Collective Code Ownership:</strong> Anyone can modify any part of the system.</li><li><strong>On-Site Customer:</strong> A customer must be resident at the development site or very easily accessible.</li></ul></li><li><p><strong>Advantages:</strong> High code quality, reduced bugs, minimized technical debt, reduced fear of change.</p></li><li><p><strong>Disadvantages:</strong> High learning curve and concentration required to introduce practices, resistance to pair programming, difficulty securing an on-site customer.</p></li></ul><h4 id="_1-2-scrum-project-management-framework" tabindex="-1"><strong>1.2 Scrum - Project Management Framework</strong> <a class="header-anchor" href="#_1-2-scrum-project-management-framework" aria-label="Permalink to “1.2 Scrum - Project Management Framework”">​</a></h4><p>Scrum is a <strong>project management framework</strong> for developing and managing complex products. It clearly defines roles, decision-making structures, and events regarding who, what, and when.</p><ul><li><p><strong>Philosophy:</strong> Based on Empiricism, it solves complex problems through a cycle of <strong>transparency, inspection, and adaptation</strong>.</p></li><li><p><strong>Scope of Application:</strong> Applied across the entire <strong>project management and collaboration process</strong>.</p></li><li><p><strong>Cycle:</strong> Work is done in fixed-length (usually 2-4 weeks) time-boxes called <strong>Sprints</strong>.</p></li><li><p><strong>Core Roles:</strong></p><ul><li><strong>Product Owner (PO):</strong> Responsible for maximizing product value, managing requirements in the <strong>Product Backlog</strong>, and prioritizing them.</li><li><strong>Scrum Master (SM):</strong> Coaches the team to follow Scrum effectively and removes obstacles. A <strong>servant leader</strong>, not a manager.</li><li><strong>Development Team:</strong> A cross-functional and self-organizing team that actually builds the product.</li></ul></li><li><p><strong>Core Artifacts:</strong></p><ul><li><strong>Product Backlog:</strong> A prioritized list of all features, improvements, and fixes needed for the product.</li><li><strong>Sprint Backlog:</strong> Product Backlog items selected to be performed in the current sprint and the plan to complete them.</li><li><strong>Increment:</strong> The &#39;working product&#39; outcome produced at the end of a sprint.</li></ul></li><li><p><strong>Core Events:</strong> (All Time-boxed)</p><ul><li><strong>Sprint Planning:</strong> Plan what to do and how to do it.</li><li><strong>Daily Scrum:</strong> A 15-minute meeting to share progress and identify obstacles.</li><li><strong>Sprint Review:</strong> Show the outcome to customers/stakeholders and receive feedback.</li><li><strong>Sprint Retrospective:</strong> Review the team&#39;s process and derive improvements.</li></ul></li><li><p><strong>Advantages:</strong> Clear roles and responsibilities, periodic feedback and adaptation, transparent progress, induces team self-organization.</p></li><li><p><strong>Disadvantages:</strong> No direct guidance on engineering practices (quality relies on the team), rigidity due to prohibiting changes during a sprint (changes wait until the next sprint).</p></li></ul><h4 id="_1-3-kanban-continuous-flow-improvement-system" tabindex="-1"><strong>1.3 Kanban - Continuous Flow Improvement System</strong> <a class="header-anchor" href="#_1-3-kanban-continuous-flow-improvement-system" aria-label="Permalink to “1.3 Kanban - Continuous Flow Improvement System”">​</a></h4><p>Kanban is a <strong>Continuous Flow system</strong> that visualizes <strong>Flow</strong> of work and limits Work In Progress (WIP) to maximize efficiency. It focuses on gradual process improvement.</p><ul><li><p><strong>Philosophy:</strong> &quot;Accept the current process as the starting point, and pursue continuous improvement through gradual change.&quot;</p></li><li><p><strong>Scope of Application:</strong> <strong>Applicable to any process</strong>. (Development, maintenance, marketing, HR, etc.)</p></li><li><p><strong>Cycle:</strong> It is <strong>Continuous</strong>. There is no time-box concept, and the next task is started as soon as a task is completed.</p></li><li><p><strong>Core Practices:</strong></p><ul><li><strong>Visualize:</strong> Use a <strong>Kanban Board</strong> to show the workflow and status (e.g., To Do, In Progress, Done) at a glance.</li><li><strong>WIP Limit:</strong> Limit the maximum number of tasks that can be performed simultaneously at each stage (especially &#39;In Progress&#39;). This identifies and resolves bottlenecks and increases team concentration.</li><li><strong>Manage Flow:</strong> Observe how work flows on the board, measure wait time, delays, and bottlenecks to continuously smooth the flow.</li><li><strong>Explicit Policies:</strong> Clarify the definitions and Definition of Done (DoD) criteria for each work stage.</li><li><strong>Feedback Loops:</strong> Regularly hold operations meetings, delivery meetings, etc., to review flow and quality.</li></ul></li><li><p><strong>Advantages:</strong> Very flexible and can respond immediately to changes, low barrier to entry, excellent for identifying bottlenecks and reducing Cycle Time.</p></li><li><p><strong>Disadvantages:</strong> Roles and deadlines are not clear, making it difficult without team discipline; difficult to make long-term plans; the pace of change may be slow.</p></li></ul><h4 id="_1-4-comparison-summary-table" tabindex="-1"><strong>1.4 Comparison Summary Table</strong> <a class="header-anchor" href="#_1-4-comparison-summary-table" aria-label="Permalink to “1.4 Comparison Summary Table”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;"><strong>eXtreme Programming (XP)</strong></th><th style="text-align:left;"><strong>Scrum</strong></th><th style="text-align:left;"><strong>Kanban</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Essence</strong></td><td style="text-align:left;"><strong>Set of Engineering Practices</strong></td><td style="text-align:left;"><strong>Project Management Framework</strong></td><td style="text-align:left;"><strong>Continuous Flow Improvement System</strong></td></tr><tr><td style="text-align:left;"><strong>Focus</strong></td><td style="text-align:left;">Code quality, technical excellence</td><td style="text-align:left;">Team collaboration, value delivery, adaptation</td><td style="text-align:left;">Workflow efficiency, wait time reduction</td></tr><tr><td style="text-align:left;"><strong>Cycle</strong></td><td style="text-align:left;">Iteration (1-2 weeks)</td><td style="text-align:left;">Sprint (2-4 weeks, fixed)</td><td style="text-align:left;">Continuous (No Time-box)</td></tr><tr><td style="text-align:left;"><strong>Change Response</strong></td><td style="text-align:left;">Possible even within Iteration</td><td style="text-align:left;">Prohibited during Sprint</td><td style="text-align:left;">Possible anytime (Very flexible)</td></tr><tr><td style="text-align:left;"><strong>Roles</strong></td><td style="text-align:left;">Coach, Customer, Developer</td><td style="text-align:left;">PO, SM, Dev Team</td><td style="text-align:left;">Does not enforce specific roles</td></tr><tr><td style="text-align:left;"><strong>Core Tools</strong></td><td style="text-align:left;">TDD, Pair Programming, CI</td><td style="text-align:left;">Sprint Backlog, Burndown Chart</td><td style="text-align:left;"><strong>Kanban Board, WIP Limit</strong></td></tr><tr><td style="text-align:left;"><strong>Metrics</strong></td><td style="text-align:left;">Unit test coverage, etc.</td><td style="text-align:left;">Velocity</td><td style="text-align:left;"><strong>Cycle Time, Throughput</strong></td></tr><tr><td style="text-align:left;"><strong>Suitable Situation</strong></td><td style="text-align:left;">Requirements change very often, high quality required</td><td style="text-align:left;">Clear goals and fast delivery needed</td><td style="text-align:left;">Maintenance, irregular workload, gradual improvement</td></tr></tbody></table><hr><h3 id="_2-the-relationship-between-the-three-methodologies-complementary-and-evolutionary" tabindex="-1">2. The Relationship Between the Three Methodologies: Complementary and Evolutionary <a class="header-anchor" href="#_2-the-relationship-between-the-three-methodologies-complementary-and-evolutionary" aria-label="Permalink to “2. The Relationship Between the Three Methodologies: Complementary and Evolutionary”">​</a></h3><p>XP, Scrum, and Kanban are not competing methodologies. They solve different problems and have a <strong>complementary</strong> and <strong>evolutionary relationship</strong>.</p><ol><li><strong>Scrum + XP: The Most Common Powerful Combination</strong></li></ol><ul><li>Scrum provides a management framework for <strong>&#39;What to do&#39;</strong> and <strong>&#39;When to do it&#39;</strong>.</li><li>XP provides engineering practices for <strong>&#39;How to do it well&#39;</strong>.</li><li>Thus, it is very natural for a Scrum team to adopt XP practices (TDD, CI, Refactoring) to produce the Increment promised in the sprint with <strong>high quality</strong> at a <strong>sustainable</strong> pace. Scrum can be seen as providing the skeleton, and XP providing the flesh.</li></ul><ol start="2"><li><strong>Kanban -&gt; Scrum: The Path of Gradual Agile Adoption</strong></li></ol><ul><li>Kanban improves gradually, starting with visualization and WIP limits without breaking the existing process.</li><li>Therefore, an organization adopting Agile/Scrum for the first time can take an <strong>evolutionary approach</strong>: visualizing the current state and improving flow with Kanban, then gradually introducing Scrum&#39;s Roles, Events, and Artifacts.</li></ul><ol start="3"><li><strong>Scrum -&gt; Kanban: Expanding Scrum&#39;s Flexibility (Scrumban)</strong></li></ol><ul><li>When a Scrum team needs a more flexible workflow without sprint boundaries (e.g., a maintenance team), they integrate Kanban&#39;s flow-centric approach.</li><li>This is called <strong>Scrumban</strong>, maintaining Scrum disciplines like sprint planning/review/retrospective, while conducting daily scrums and work execution as a continuous flow using a Kanban board and WIP limits.</li></ul><hr><h3 id="_3-practical-integration-of-scrum-xp-and-kanban" tabindex="-1">3. Practical Integration of Scrum, XP, and Kanban <a class="header-anchor" href="#_3-practical-integration-of-scrum-xp-and-kanban" aria-label="Permalink to “3. Practical Integration of Scrum, XP, and Kanban”">​</a></h3><p>An ideal team harmoniously blends the strengths of the three methodologies. Below is how to systematically apply this.</p><h4 id="_3-1-integration-principles" tabindex="-1"><strong>3.1 Integration Principles</strong> <a class="header-anchor" href="#_3-1-integration-principles" aria-label="Permalink to “3.1 Integration Principles”">​</a></h4><ol><li><strong>Use Scrum as the Backbone:</strong> The framework for project management and collaboration follows Scrum&#39;s roles, events, and artifacts.</li><li><strong>Ensure Quality with XP Practices:</strong> Actively adopt XP practices in the development phase for code quality and a sustainable pace.</li><li><strong>Improve the Process with Kanban&#39;s Flow:</strong> Utilize Kanban boards and WIP limits to manage workflow within sprints and identify bottlenecks.</li></ol><h4 id="_3-2-step-by-step-checklist-integration-application-roadmap" tabindex="-1"><strong>3.2 Step-by-Step Checklist (Integration Application Roadmap)</strong> <a class="header-anchor" href="#_3-2-step-by-step-checklist-integration-application-roadmap" aria-label="Permalink to “3.2 Step-by-Step Checklist (Integration Application Roadmap)”">​</a></h4><p><strong>🔹 Phase 1: Preparation and Introduction (1-2 months)</strong></p><ul><li>[ ] <strong>Stakeholder Training:</strong> Ensure all members (developers, managers, customers) understand the basic concepts and integration purposes of Scrum, XP, and Kanban.</li><li>[ ] <strong>Establish Scrum Framework:</strong><ul><li>[ ] Appoint a <strong>Product Owner</strong> and initially draft the <strong>Product Backlog</strong>.</li><li>[ ] Appoint a <strong>Scrum Master</strong>.</li><li>[ ] Form a <strong>Development Team</strong> (cross-functional if possible).</li><li>[ ] Determine the <strong>Sprint cycle</strong> (e.g., 2 weeks).</li></ul></li><li>[ ] <strong>Tool Setup:</strong> Set up a collaboration tool with <strong>Kanban Board</strong> functionality, like Jira, Trello, Azure Boards. (Physical Board is also possible)</li></ul><p><strong>🔹 Phase 2: Execute First Sprint and Introduce XP Practices (3-6 months)</strong></p><ul><li>[ ] <strong>Execute Scrum Events:</strong><ul><li>[ ] <strong>Sprint Planning:</strong> Establish the Sprint Backlog with the PO.</li><li>[ ] <strong>Daily Scrum:</strong> Share progress while looking at the Kanban Board. (&quot;Talk to the board&quot;)</li><li>[ ] <strong>Sprint Review &amp; Retrospective:</strong> Review the first sprint results and discuss improvements.</li></ul></li><li>[ ] <strong>Utilize Kanban Board:</strong><ul><li>[ ] Place Sprint Backlog items on the &#39;To Do&#39; column of the Kanban Board.</li><li>[ ] Set up the Kanban board stages to fit the team&#39;s situation. (e.g., <code>To Do</code> -&gt; <code>Development</code> -&gt; <code>Code Review</code> -&gt; <code>Testing</code> -&gt; <code>Done</code>)</li><li>[ ] <strong>Start applying WIP Limits from the &#39;Development&#39; stage.</strong> (e.g., Number of developers * 1.5)</li></ul></li><li>[ ] <strong>Introduce XP Practices (Step-by-step, one by one):</strong><ul><li>[ ] <strong>Introduce CI (Continuous Integration):</strong> Build an automated build/test environment. (<strong>Highest priority</strong>)</li><li>[ ] <strong>Introduce TDD:</strong> Train a culture of writing test cases first, starting with core modules.</li><li>[ ] <strong>Secure Refactoring Time:</strong> Explicitly include refactoring tasks as Tasks during sprint planning.</li></ul></li></ul><p><strong>🔹 Phase 3: Maturity and Advancement (Over 6 months)</strong></p><ul><li>[ ] <strong>Quantify and Improve Process:</strong><ul><li>[ ] <strong>Measure Cycle Time/Throughput:</strong> Measure the team&#39;s average processing speed through Kanban metrics.</li><li>[ ] <strong>Measure Velocity:</strong> Measure Scrum Velocity to increase prediction accuracy.</li><li>[ ] <strong>Adjust WIP Limits:</strong> Optimize WIP Limits based on data and team intuition.</li></ul></li><li>[ ] <strong>Deepen XP Practices:</strong><ul><li>[ ] <strong>Try Pair Programming:</strong> Try it for difficult bug fixes or onboarding new hires.</li><li>[ ] <strong>Simple Design:</strong> Periodically discuss design complexity in retrospectives.</li></ul></li><li>[ ] <strong>Establish Culture:</strong><ul><li>[ ] <strong>Remove Fear of Failure:</strong> Establish a culture of making mistakes learning opportunities through TDD and retrospectives.</li><li>[ ] <strong>Encourage Team Self-organization:</strong> The Scrum Master guides the team to solve problems themselves through coaching, not commands.</li></ul></li></ul><h4 id="_3-3-integrated-operation-diagram-flow-of-one-sprint" tabindex="-1"><strong>3.3 Integrated Operation Diagram: &quot;Flow of One Sprint&quot;</strong> <a class="header-anchor" href="#_3-3-integrated-operation-diagram-flow-of-one-sprint" aria-label="Permalink to “3.3 Integrated Operation Diagram: &quot;Flow of One Sprint&quot;”">​</a></h4>`,39),(r(),e(n,null,{default:t(()=>[i(h,{id:`mermaid-671`,class:`mermaid`,graph:`flowchart%20TD%0A%20%20%20%20A%5B%3Cb%3EProduct%20Backlog%3C%2Fb%3E%3Cbr%3EPO%20manages%20priorities%5D%20--%3E%20B%5BSprint%20Planning%20Meeting%5D%3B%0A%0A%20%20%20%20subgraph%20B%20%5BScrum%20Event%3A%20Planning%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20B1%5BPO%3A%20What%3Cbr%3EWhat%20to%20build%3F%5D%20--%3E%20B2%5BDev%20Team%3A%20How%3Cbr%3EHow%20to%20build%20it%3F%3Cbr%3EDecompose%20into%20Tasks%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20B%20--%3E%20C%5B%3Cb%3ESprint%20Backlog%3C%2Fb%3E%3Cbr%3ETask%20unit%20list%5D%3B%0A%20%20%20%20C%20--%3E%20D%5BPlace%20Tasks%20on%20%3Cb%3EKanban%20Board%3C%2Fb%3E%5D%3B%0A%0A%20%20%20%20subgraph%20E%20%5BWork%20Execution%20in%20Sprint%3Cbr%3EXP%20%2B%20Kanban%5D%0A%20%20%20%20%20%20%20%20direction%20TB%0A%20%20%20%20%20%20%20%20F%5BTo%20Do%3Cbr%3EWaiting%5D%20--%3E%20G%5BDevelopment%3Cbr%3EWIP%20Limit%3A%204%3Cbr%3E**Apply%20XP%20Practices**%3Cbr%3E-%20TDD%3Cbr%3E-%20Pair%20Programming%3Cbr%3E-%20CI%5D%3B%0A%20%20%20%20%20%20%20%20G%20--%3E%20H%5BCode%20Review%3Cbr%3EWIP%20Limit%3A%202%5D%3B%0A%20%20%20%20%20%20%20%20H%20--%3E%20I%5BTesting%5D%3B%0A%20%20%20%20%20%20%20%20I%20--%3E%20J%5BDone%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20D%20--%3E%20E%3B%0A%0A%20%20%20%20subgraph%20K%20%5BScrum%20Event%3A%20Daily%5D%0A%20%20%20%20%20%20%20%20L%5B%3Cb%3EDaily%20Scrum%3C%2Fb%3E%3Cbr%3EShare%20progress%3Cbr%3EIdentify%20obstacles%3Cbr%3Ewhile%20looking%20at%20the%20board%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20E%20--%3E%20L%3B%0A%20%20%20%20J%20--%3E%20M%5B%3Cb%3EIncrement%3C%2Fb%3E%3Cbr%3EWorking%20software%5D%3B%0A%0A%20%20%20%20subgraph%20N%20%5BScrum%20Event%3A%20Inspect%20and%20Adapt%5D%0A%20%20%20%20%20%20%20%20direction%20LR%0A%20%20%20%20%20%20%20%20O%5BSprint%20Review%3Cbr%3EDemo%20Increment%20to%3Cbr%3ECustomers%2FPO%3Cbr%3EReflect%20feedback%5D%3B%0A%20%20%20%20%20%20%20%20P%5BSprint%20Retrospective%3Cbr%3EDerive%20process%20improvements%3Cbr%3Eex%3A%20%22Adjust%20WIP%20Limit%22%3Cbr%3E%22Expand%20TDD%20application%20scope%22%5D%3B%0A%20%20%20%20end%0A%0A%20%20%20%20M%20--%3E%20N%3B%0A%20%20%20%20O%20--%3E%20A%3B%0A%20%20%20%20P%20--%3E%20A%3B%0A`})]),fallback:t(()=>[...u[0]||=[s(` Loading... `,-1)]]),_:1})),u[2]||=a(`<hr><h3 id="conclusion-find-the-optimal-combination-for-your-situation" tabindex="-1">Conclusion: Find the Optimal Combination for Your Situation <a class="header-anchor" href="#conclusion-find-the-optimal-combination-for-your-situation" aria-label="Permalink to “Conclusion: Find the Optimal Combination for Your Situation”">​</a></h3><p>There is no &quot;silver bullet&quot; methodology. XP, Scrum, and Kanban are tools with their own distinct strengths and focuses.</p><ul><li>For <strong>teams needing to develop new products quickly</strong>, an &#39;integrated approach&#39;—using <strong>Scrum&#39;s</strong> structure as a backbone, ensuring quality with <strong>XP</strong> practices, and smoothing the workflow within sprints using a <strong>Kanban</strong> board—is highly effective.</li><li>For <strong>teams primarily handling maintenance</strong>, using <strong>Kanban</strong> as the main tool, improving through regular <strong>retrospectives (Scrum)</strong>, and applying <strong>TDD (XP)</strong> for critical bug fixes is possible.</li></ul><p>The most important thing is for the team to recognize their own situation and problems, understand the principles and values of these methodologies, and <strong>continuously experiment and improve</strong>. I hope this guide serves as a starting point for that journey.</p><hr><h2 id="🧠-software-development-speed-and-its-limits-in-the-ai-era-geeknews-chatgpt-summary" tabindex="-1">🧠 Software Development Speed and its Limits in the AI Era (GeekNews Chatgpt Summary) <a class="header-anchor" href="#🧠-software-development-speed-and-its-limits-in-the-ai-era-geeknews-chatgpt-summary" aria-label="Permalink to “🧠 Software Development Speed and its Limits in the AI Era (GeekNews Chatgpt Summary)”">​</a></h2><ul><li>Source: <a href="https://news.hada.io/topic?id=23013" target="_blank" rel="noreferrer">Should we reconsider eXtreme Programming (XP) in the AI era?</a></li></ul><ul><li>AI tools and platform innovations have dramatically improved code generation speed, but project success rates remain low and failure rates high.</li><li>The problem is not speed, but the lack of verification and alignment, and XP induces learning, alignment, and quality improvement through intentional constraints.</li></ul><hr><h2 id="⚖️-the-role-of-xp-a-counterweight-to-speed" tabindex="-1">⚖️ The Role of XP: A Counterweight to Speed <a class="header-anchor" href="#⚖️-the-role-of-xp-a-counterweight-to-speed" aria-label="Permalink to “⚖️ The Role of XP: A Counterweight to Speed”">​</a></h2><ul><li>Unlimited acceleration causes problems depriving opportunities for learning, discovering mistakes, and course-correcting.</li><li>XP is designed to introduce intentional friction and constraints to keep the team moving in the right direction.</li><li>Representative practice: Pair programming intentionally halves output.</li><li>While pair programming might halve output, it provides double the positive effects, such as shared understanding, trust, quality, and capability improvement within the team.</li></ul><hr><h2 id="🤖-awareness-of-xp-problems-deepening-with-ai" tabindex="-1">🤖 Awareness of XP Problems Deepening with AI <a class="header-anchor" href="#🤖-awareness-of-xp-problems-deepening-with-ai" aria-label="Permalink to “🤖 Awareness of XP Problems Deepening with AI”">​</a></h2><ul><li>As AI makes code generation effortless, the risk of mass-producing poorly verified software increases.</li><li>Unconstrained automation systems layer unverified logic, worsening complexity and vulnerability.</li><li>Recent studies prove that as the context window of LLMs gets longer, accuracy deteriorates.</li><li>This results in highly maintainable and easily broken code, and XP originated to prevent such chaotic entropy.</li></ul><hr><h2 id="🧑‍💻-software-is-still-the-domain-of-humans" tabindex="-1">🧑‍💻 Software is Still the Domain of Humans <a class="header-anchor" href="#🧑‍💻-software-is-still-the-domain-of-humans" aria-label="Permalink to “🧑‍💻 Software is Still the Domain of Humans”">​</a></h2><ul><li>Even if AI advances, the essence of software being made by humans for humans, within organizational communication and culture, remains unchanged.</li><li>The major obstacles to delivery are not the degree of automation, but human-based factors like alignment, shared context, clear outcomes, and user verification.</li><li>XP&#39;s core values: Simplicity, Communication, Feedback, Respect, Courage.</li></ul><hr><h2 id="🚀-from-feature-factory-to-delivering-real-value" tabindex="-1">🚀 From Feature Factory to Delivering Real Value <a class="header-anchor" href="#🚀-from-feature-factory-to-delivering-real-value" aria-label="Permalink to “🚀 From Feature Factory to Delivering Real Value”">​</a></h2><ul><li>Successful teams prioritize flow and feedback over speed itself.</li><li>XP practices like small batches, continuous integration, automated testing, and collective ownership contribute to adaptability and user-centricity.</li><li>As code production gets faster in the future, these methods become essential for managing quality, risk, and intent.</li></ul><hr><h2 id="📉-lessons-from-the-past" tabindex="-1">📉 Lessons from the Past <a class="header-anchor" href="#📉-lessons-from-the-past" aria-label="Permalink to “📉 Lessons from the Past”">​</a></h2><ul><li>CHAOS Report Statistics: <ul><li>1994: 16% of projects succeeded on time and within budget.</li><li>2012: Improved to 37%.</li><li>2020: Dropped back to 31%.</li></ul></li><li>After over 20 years of innovation and change (agile, DevOps, cloud-native, AI, etc.), overall reliability has only increased by 14 percentage points.</li><li>Toolchains alone cannot solve the problem.</li><li>Reaffirming the importance of proper methodologies.</li></ul><hr><h2 id="🔮-what-is-needed-in-the-future" tabindex="-1">🔮 What is Needed in the Future <a class="header-anchor" href="#🔮-what-is-needed-in-the-future" aria-label="Permalink to “🔮 What is Needed in the Future”">​</a></h2><ol><li>Output is no longer a constraint: Code production capacity outpaces verification and alignment speed.</li><li>Outcome-centric capability enhancement: Feedback, clear product direction, strong collaboration, and excellent design are essential.</li><li>More human-centric processes needed: Even if AI advances, continuous delivery relies on collaboration.</li></ol><ul><li>Emphasizes that an effective Product Operating Model actually comes from human-centric operations—collaboration, clarity, flow.</li><li>Rather than technical innovation (platform), seamlessly aligning team strategy, operational rhythm, and engineering practices makes it possible to build a sustainable software delivery environment in the AI era.</li></ul><hr><h2 id="✅-conclusion-is-xp-necessary-in-the-ai-era" tabindex="-1">✅ Conclusion: Is XP necessary in the AI era? <a class="header-anchor" href="#✅-conclusion-is-xp-necessary-in-the-ai-era" aria-label="Permalink to “✅ Conclusion: Is XP necessary in the AI era?”">​</a></h2><ul><li>Yes.</li><li>Amidst increasingly powerful tools, frameworks are needed to anchor human-centric practices.</li><li>XP provides team-centricity, empathy, shared understanding, and correct goal orientation simultaneously.</li><li>Focus on meaningful directionality and intra-team alignment rather than simple output speed.</li><li>In an era of AI acceleration and unconstrained production, XP is a rare methodology that reminds us software is human work.</li></ul>`,31)])}var p=o(d,[[`render`,f]]);export{u as __pageData,p as default};